                        break;
                    case 4:
                        if (f_profile_image is global::MessagePack.Formatters.StringFormatter<TWriteBuffer, TReadBuffer>)
                        {
                            result.profile_image = buffer.ReadString();
                        }
                        else
                        {
                            var v = result.profile_image;
                            f_profile_image.Deserialize(ref buffer, ref state, ref v);
                            result.profile_image = v;
                        }
                        break;
                    case 5:
                        if (f_link is global::MessagePack.Formatters.StringFormatter<TWriteBuffer, TReadBuffer>)
                        {
                            result.link = buffer.ReadString();
                        }
                        else
                        {
                            var v = result.link;
                            f_link.Deserialize(ref buffer, ref state, ref v);
                            result.link = v;
                        }
                        break;
                    case 6:
                        result.accept_rate = buffer.TryReadNil() ? default(int?) : buffer.ReadInt32();
                        break;
                    case 7:
                        {
                            var v = result.badge_counts;
                            f_badge_counts.Deserialize(ref buffer, ref state, ref v);
