        }
    }
}

namespace AnswerTwins.Copy
{
    using SerializerFoundation;
    using System.Buffers.Binary;
    using System.Runtime.CompilerServices;
    using MessagePack;
    using static MessagePack.MessagePackPrimitives;

    internal sealed class BadgeCountFormatter<TWriteBuffer, TReadBuffer> : IMessagePackFormatter<TWriteBuffer, TReadBuffer, global::BadgeCount?>
        where TWriteBuffer : struct, IWriteBuffer
        #if NET9_0_OR_GREATER
        , allows ref struct
        #endif
        where TReadBuffer : struct, IReadBuffer
        #if NET9_0_OR_GREATER
        , allows ref struct
        #endif
    {

        public void Initialize(MessagePackFormatterResolver resolver)
        {
        }

        public void Serialize(ref TWriteBuffer buffer, ref SerializeState state, global::BadgeCount? value)
        {
            if (value is null)
            {
                buffer.WriteNil();
                return;
            }

            state.Enter();

            {
                ref var d = ref buffer.GetReference(1 + MaxInt32Length + MaxInt32Length + MaxInt32Length);
                var w = 0;
                w += UnsafeWriteFixArrayHeader(ref Unsafe.Add(ref d, w), 3);
                w += value.gold is { } nv_gold ? UnsafeWriteInt32(ref Unsafe.Add(ref d, w), nv_gold) : UnsafeWriteNil(ref Unsafe.Add(ref d, w));
                w += value.silver is { } nv_silver ? UnsafeWriteInt32(ref Unsafe.Add(ref d, w), nv_silver) : UnsafeWriteNil(ref Unsafe.Add(ref d, w));
                w += value.bronze is { } nv_bronze ? UnsafeWriteInt32(ref Unsafe.Add(ref d, w), nv_bronze) : UnsafeWriteNil(ref Unsafe.Add(ref d, w));
                buffer.Advance(w);
            }
            state.Exit();
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        public void Deserialize(ref TReadBuffer buffer, ref DeserializeState state, ref global::BadgeCount? value)
        {
            if (buffer.TryReadNil())
            {
                value = null;
                return;
            }

            var result = value ?? new global::BadgeCount();
            state.Enter();

            var count = buffer.ReadArrayHeader(ref state);
            for (int i = 0; i < count; i++)
            {
                switch (i)
                {
                    case 0:
                        result.gold = buffer.TryReadNil() ? default(int?) : buffer.ReadInt32();
                        break;
                    case 1:
                        result.silver = buffer.TryReadNil() ? default(int?) : buffer.ReadInt32();
                        break;
                    case 2:
                        result.bronze = buffer.TryReadNil() ? default(int?) : buffer.ReadInt32();
                        break;
                    default:
                        buffer.Skip(); // version tolerance: unknown trailing member
                        break;
                }
            }

            state.Exit();
            value = result;
        }
    }
}

namespace AnswerTwins.Copy
{
    public sealed partial class TwinFormatterFactory : global::MessagePack.MessagePackFormatterFactory
    {
        public override object? CreateFormatter<TWriteBuffer, TReadBuffer>(global::System.Type type)
        {
            if (type == typeof(global::Answer)) return new AnswerFormatter<TWriteBuffer, TReadBuffer>();
            if (type == typeof(global::Comment)) return new CommentFormatter<TWriteBuffer, TReadBuffer>();
            if (type == typeof(global::ShallowUser)) return new ShallowUserFormatter<TWriteBuffer, TReadBuffer>();
            if (type == typeof(global::BadgeCount)) return new BadgeCountFormatter<TWriteBuffer, TReadBuffer>();
            return null;
        }
    }
}
